		vcexecutequery
		<Описание>Выполняет в базе запрос на языке 1С, переданный в аргументе querytext, и возвращает результат в текстовом виде; ошибка запроса возвращается текстом «Ошибка запроса: …». Все параметры запроса должны быть заданы непосредственно в тексте запроса. Запрос должен быть строго в одну строку, без переноса строк.</Описание>
		<ЗапросКод>Результат = "";
Запрос = Новый Запрос;
Запрос.Текст = ТекстЗапроса;
ТаблицаРезультата = Неопределено;
Попытка
	ТаблицаРезультата = Запрос.Выполнить().Выгрузить();
Исключение
	// Без перехвата ошибка запроса (неверное поле, синтаксис) возвращалась пустым ответом.
	Результат = "Ошибка запроса: " + КраткоеПредставлениеОшибки(ИнформацияОбОшибке());
КонецПопытки;

Если ТаблицаРезультата <> Неопределено Тогда

	Разделитель = " | ";

	ЧастиЗаголовка = Новый Массив;
	Для Каждого Колонка Из ТаблицаРезультата.Колонки Цикл
		ЧастиЗаголовка.Добавить(Колонка.Имя);
	КонецЦикла;

	Результат = СтрСоединить(ЧастиЗаголовка, Разделитель);

	Для Каждого СтрокаТаблицы Из ТаблицаРезультата Цикл
		ЧастиСтроки = Новый Массив;
		Для Каждого Колонка Из ТаблицаРезультата.Колонки Цикл
			ЧастиСтроки.Добавить(Строка(СтрокаТаблицы[Колонка.Имя]));
		КонецЦикла;
		Результат = Результат + Символы.ПС + СтрСоединить(ЧастиСтроки, Разделитель);
	КонецЦикла;

	Если ТаблицаРезультата.Количество() = 0 Тогда
		Результат = Результат + Символы.ПС + "(0 строк)";
	КонецЕсли;

КонецЕсли;
</ЗапросКод>
		<ВариантОтчета>00000000-0000-0000-0000-000000000000</ВариантОтчета>
		<Параметры>
			<Имя>ТекстЗапроса</Имя>
			<ИмяEn>querytext</ИмяEn>
			<Описание>Текст запроса на языке 1С</Описание>
		</Параметры>
